import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'aIFZHrVtBLCNlrEdxIud',titulo:'Patrulha Canina - Playset De Acampamento Com Bag E 3 Bonecos Lilás',listing:'MLB6191360194'},{id:'aozkBGONt1bYjzktRNP7',titulo:'Tênis Masculino Feminino Kappa Park 2.0 Original',listing:'MLB4049279695'}];
test('triagem62 protege identidade variante campos operacionais e idempotência',()=>{for(const r of rows){const p={...r,preco:'salvo',historico:'preservado',linkAfiliado:'https://meli.la/preservar',variation_id:'200022329787'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.deepEqual(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{id:'outro'},{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');}});
test('Patrulha não atribui medidas a cada boneco ou certifica faixa etária',()=>{const x=correctProductData(rows[0]);assert.equal(x.titulo,rows[0].titulo);assert.match(x.comentario,/não atribuímos essas dimensões a cada boneco/);assert.match(x.comentario,/3 anos é informada no anúncio/);assert.doesNotMatch(x.pros,/certifica|seguro|23|8,4|32,5|3 anos/i);});
test('Kappa separa descrição da oferta de recomendação oficial e autenticidade',()=>{const x=correctProductData(rows[1]);assert.equal(x.titulo,'Tênis Kappa Park 2.0 unissex');assert.match(x.comentario,/não é apresentada como recomendação oficial/);assert.match(x.comentario,/não representa autenticação/);assert.doesNotMatch(x.pros,/EVA-K|certifica|ideal|original|corrida/i);});
test('LG 32RL601CBSA preserva conteúdo sem transferir modelo 32LR651CBSA',()=>{const p={id:'aIWLmzyxlViGPWt6Mctg',titulo:'Smart TV Profissional LG 32" LED HD - 32RL601CBSA',comentario:'Resumo anterior com som virtual 5.1',comparison:null},x=correctProductData(p);for(const key of Object.keys(p))assert.deepEqual(x[key],p[key]);});
